insert into public.academy_missions(id,version,config,published) values
('primeiro-voo',1,$mission${"id":"primeiro-voo","title":"Primeiro voo","scene":"field","brief":"Decole, estabilize a aeronave sobre H e visite os marcadores na ordem. Use W/S para altitude, A/D para giro e setas para deslocamento. Volte e pouse na base.","goals":[{"kind":"point","label":"Pairar 20 s acima da base","x":0,"z":0,"h":12,"radius":6,"tolerance":4,"seconds":20},{"kind":"point","label":"Visitar o marcador 2","x":20,"z":-25,"h":15,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Visitar o marcador 3","x":-20,"z":-45,"h":15,"radius":6,"tolerance":4,"seconds":2},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":1,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('precisao',1,$mission${"id":"precisao","title":"Circuito de precisão","scene":"course","brief":"Atravesse os seis portais em ordem. Demonstre Cine, Normal e Sport nas etapas indicadas. Sport não oferece assistência de obstáculos.","goals":[{"kind":"mode","label":"Demonstrar Cine","value":"Cine","seconds":6},{"kind":"point","label":"Portal 1","x":0,"z":-25,"h":12,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Portal 2","x":25,"z":-45,"h":18,"radius":6,"tolerance":4,"seconds":2},{"kind":"mode","label":"Demonstrar Normal","value":"Normal","seconds":6},{"kind":"point","label":"Portal 3","x":45,"z":-15,"h":22,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Portal 4","x":25,"z":20,"h":18,"radius":6,"tolerance":4,"seconds":2},{"kind":"mode","label":"Demonstrar Sport em área livre","value":"Sport","seconds":6},{"kind":"point","label":"Portal 5","x":-20,"z":25,"h":15,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Portal 6","x":-25,"z":-10,"h":12,"radius":6,"tolerance":4,"seconds":2},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":2,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('solar',1,$mission${"id":"solar","title":"Telhado para instalação solar","scene":"roof","brief":"Inspecione o telhado azul a norte da base. Aproxime-se com segurança, use gimbal e zoom e fotografe os quatro marcadores laranja na ordem. O alvo deve estar centralizado na câmera, a menos de 65 m.","goals":[{"kind":"setting","label":"Ajustar zoom para pelo menos 1,5×","key":"zoom","minimum":1.5,"seconds":1},{"kind":"setting","label":"Selecionar exposição Pro","key":"exposure","value":"Pro","seconds":1},{"kind":"photo","label":"Fotografar face sul","x":0,"z":-62,"h":14,"radius":65,"seconds":0},{"kind":"photo","label":"Fotografar face leste","x":17,"z":-77,"h":14,"radius":65,"seconds":0},{"kind":"photo","label":"Fotografar face norte","x":0,"z":-92,"h":14,"radius":65,"seconds":0},{"kind":"photo","label":"Fotografar obstáculo no telhado","x":-12,"z":-77,"h":18,"radius":65,"seconds":0},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":3,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('area',1,$mission${"id":"area","title":"Inspeção de área","scene":"survey","brief":"Planeje uma rota no mapa com os seis setores, execute Waypoints e visite os marcadores. A rota pode ser editada no menu WP. Supervisione e finalize com retorno à base.","goals":[{"kind":"auto","label":"Demonstrar Waypoints por 8 s","value":"Waypoints","seconds":8},{"kind":"point","label":"Setor 1","x":0,"z":-30,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Setor 2","x":35,"z":-30,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Setor 3","x":35,"z":-70,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Setor 4","x":0,"z":-70,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Setor 5","x":-35,"z":-70,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Setor 6","x":-35,"z":-30,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"auto","label":"Demonstrar rth por 3 s","value":"rth","seconds":3},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":4,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('evento',1,$mission${"id":"evento","title":"Cobertura de evento","scene":"event","brief":"Faça uma tomada em Cine por 10 s com gravação ativa e demonstre Dronie, Rocket e Circle. O veículo é a referência dos QuickShots. A região vermelha representa público: não sobrevoe.","goals":[{"kind":"video","label":"Gravar 10 s em Cine","value":"Cine","seconds":10},{"kind":"auto","label":"Demonstrar Dronie por 8 s","value":"Dronie","seconds":8},{"kind":"auto","label":"Demonstrar Rocket por 8 s","value":"Rocket","seconds":8},{"kind":"auto","label":"Demonstrar Circle por 8 s","value":"Circle","seconds":8},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":5,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[{"x":-55,"z":-65,"radius":20}],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('torre',1,$mission${"id":"torre","title":"Inspeção de torre","scene":"tower","brief":"A torre está a norte da base. Registre os quatro marcadores em alturas diferentes. Mantenha distância da estrutura e prepare os sensores antes do voo.","goals":[{"kind":"setting","label":"Configurar sensores para Frear","key":"avoid","value":"Frear","seconds":1},{"kind":"photo","label":"Inspecionar base da torre","x":0,"z":-56,"h":8,"radius":65,"seconds":0},{"kind":"photo","label":"Inspecionar nível intermediário","x":0,"z":-56,"h":24,"radius":65,"seconds":0},{"kind":"photo","label":"Inspecionar antena superior","x":0,"z":-56,"h":44,"radius":65,"seconds":0},{"kind":"photo","label":"Inspecionar módulo lateral","x":6,"z":-60,"h":30,"radius":65,"seconds":0},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":6,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('fachada',1,$mission${"id":"fachada","title":"Inspeção de fachada","scene":"facade","brief":"Faça o roteiro de calibração antes de voar. Fotografe os defeitos sinalizados na fachada. Na última tomada a iluminação diminui: redobre o controle manual e mantenha distância.","goals":[{"kind":"calibration","label":"Concluir um roteiro de calibração em solo","seconds":0},{"kind":"photo","label":"Fotografar fissura esquerda","x":-15,"z":-70,"h":10,"radius":65,"seconds":0},{"kind":"photo","label":"Fotografar fissura central","x":0,"z":-70,"h":20,"radius":65,"seconds":0},{"kind":"photo","label":"Fotografar fissura direita em pouca luz","x":15,"z":-70,"h":12,"radius":65,"seconds":0},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":7,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('obra',1,$mission${"id":"obra","title":"Acompanhamento de obra","scene":"construction","brief":"Registre os quatro pontos da obra e demonstre Helix, Boomerang e Asteroid em área livre, usando o veículo como referência. As manobras são aproximações didáticas.","goals":[{"kind":"photo","label":"Registrar fundação","x":-25,"z":-60,"h":2,"radius":65,"seconds":0},{"kind":"photo","label":"Registrar estrutura","x":0,"z":-75,"h":16,"radius":65,"seconds":0},{"kind":"photo","label":"Registrar cobertura","x":25,"z":-70,"h":22,"radius":65,"seconds":0},{"kind":"photo","label":"Registrar acesso","x":30,"z":-35,"h":2,"radius":65,"seconds":0},{"kind":"auto","label":"Demonstrar Helix por 8 s","value":"Helix","seconds":8},{"kind":"auto","label":"Demonstrar Boomerang por 8 s","value":"Boomerang","seconds":8},{"kind":"auto","label":"Demonstrar Asteroid por 8 s","value":"Asteroid","seconds":8},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":8,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('busca',1,$mission${"id":"busca","title":"Busca em área rural","scene":"rural","brief":"Faça a busca pelos três setores. Localize o veículo laranja, selecione-o e use ActiveTrack por 15 s. Cancele a automação e retorne.","goals":[{"kind":"point","label":"Buscar setor 1","x":-35,"z":-30,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Buscar setor 2","x":-35,"z":-70,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"point","label":"Buscar setor 3","x":30,"z":-90,"h":25,"radius":6,"tolerance":4,"seconds":2},{"kind":"auto","label":"Demonstrar track por 15 s","value":"track","seconds":15},{"kind":"manual","label":"Retomar controle manual por 5 s","seconds":5},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":9,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('contingencia',1,$mission${"id":"contingencia","title":"Missão com contingências","scene":"emergency","brief":"Antes de iniciar, configure perda de enlace para Pairar. Decole e estabilize. O sistema introduz perda de enlace, GNSS fraco, vento e bateria baixa. A recuperação dos sinais e a confirmação da origem serão simuladas pelo exercício antes da bateria baixa.","goals":[{"kind":"point","label":"Estabilizar sobre a base","x":0,"z":0,"h":15,"radius":6,"tolerance":4,"seconds":5},{"kind":"link","label":"Manter pairado durante perda de enlace (8 s)","seconds":8},{"kind":"gps","label":"Controlar com GNSS fraco e vento (8 s)","seconds":8},{"kind":"auto","label":"Demonstrar rth por 3 s","value":"rth","seconds":3},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":10,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true);
